def translate(language, message_key, **values):
    return TEXT[message_key][1 if language == 'en' else 0].format(**values)


def error_text(language, text, preserve=False):
    if preserve:
        return ERRORS.get(text, text) if language == 'en' else AR_ERRORS.get(text, text)
    detail = ERRORS.get(text, 'Unable to complete this request. Check your input or contact Support.') if language == 'en' else AR_ERRORS.get(text, text)
    title = '⚠️ Please check your request' if language == 'en' else '⚠️ يرجى مراجعة الطلب'
    return title + '\n\n' + detail
